'use strict';
const EventEmitter = require('events').EventEmitter;
class Stream extends EventEmitter {}
class Base extends EventEmitter {
  constructor() {
    super();
    this.stream = new Stream();
    this.log = [];
    this.stream.on('error', this._handleNetworkError.bind(this));
    this.stream.on('data', this.onData.bind(this));
    this.later = this.finish.bind(this);
  }
  _handleNetworkError(err) {
    this.log.push('net:' + err.message);
  }
  onData(d) { this.log.push('data:' + d); }
  finish(x) { this.log.push('fin:' + x); return this.log.length; }
}
function run() {
  const b = new Base();
  b.stream.emit('error', new Error('x'));
  b.stream.emit('data', 'r');
  const n = b.later('z');
  return b.log.join('|') + '#' + n;
}
module.exports = { run };
